cd /root && mkdir -p /root/direct-sync/maersk_ref && python3 - <<'EOF'
import json,os,re,urllib.request
env={}
for p in ("/root/.env","/root/Iryna_Karmazina/.env","/root/.n8n_env"):
    if os.path.exists(p):
        for ln in open(p):
            if "=" in ln and not ln.strip().startswith("#"):
                k,v=ln.strip().split("=",1); env.setdefault(k.strip(),v.strip().strip('"\''))
key=env.get("N8N_API_KEY") or ""
base="https://irynakarmazina.app.n8n.cloud"
r=urllib.request.Request(base+"/api/v1/workflows/JQKA35haUsXU4XqE",headers={"X-N8N-API-KEY":key})
wf=json.loads(urllib.request.urlopen(r,timeout=60).read().decode())
json.dump(wf,open("/root/direct-sync/maersk_ref/wf_crm.json","w"),ensure_ascii=False)
os.chmod("/root/direct-sync/maersk_ref/wf_crm.json",0o600)
for n in wf["nodes"]:
    p=n.get("parameters") or {}
    if n["type"].endswith("code"):
        code=p.get("jsCode","")
        fn="/root/direct-sync/maersk_ref/%s.js"%re.sub(r"\W+","_",n["name"])
        open(fn,"w").write(code); print("CODE",n["name"],len(code),"->",fn)
    if n["name"]=="Maersk Token":
        body=json.dumps(p,ensure_ascii=False)
        print("TOKEN NODE keys:",[k for k in p])
        for m in re.finditer(r'"(name|parameterName)":\s*"([^"]+)"',body):
            print("   param:",m.group(2))
        print("   має секрети:",bool(re.search(r"[A-Za-z0-9]{28,}",body)))
    if n["name"]=="Maersk API":
        print("API NODE url:",re.sub(r"[A-Za-z0-9_\-]{25,}","<masked>",str(p.get("url",""))))
        hdr=json.dumps(p.get("headerParameters") or p.get("options") or {},ensure_ascii=False)
        print("   headers:",re.sub(r"[A-Za-z0-9_\-]{25,}","<masked>",hdr)[:300])
EOF
